export const RAW_PAGES: Record<string, any> = {
  "about-us": {"handle":"about-us","seo":{"title":"About Us\n – Namo Narayana","description":"Pure Goodness, Just the Way Nature Intended At Namo Narayana, we believe good health begins with pure food. That belief inspired us to bring back the kind of desi ghee our grandparents trusted, made with patience, tradition, and honesty. In a world full of shortcuts, we chose the longer path because we believe purity i","ogImage":""},"content":"\n      <section id=\"shopify-section-template--21120678887592__about-hero\" class=\"shopify-section\">\n\n<section class=\"nn-ah\" id=\"nn-ah-template--21120678887592__about-hero\" style=\"\n    --nn-ah-height: 280px;\n    --nn-ah-overlay: #000000;\n    --nn-ah-overlay-opacity: 0.45;\n  \"><img class=\"nn-ah__bg\" src=\"//namonarayana.com/cdn/shop/files/Banner2-BG.jpg_2.jpg?v=1785269657&amp;width=2400\" alt=\"\" loading=\"eager\" style=\"object-position: bottom center;\"><span class=\"nn-ah__overlay\" aria-hidden=\"true\"></span>\n  <div class=\"nn-ah__content\"><span class=\"nn-ah__eyebrow\">Namo Narayana</span><h1 class=\"nn-ah__heading\">Pure Goodness, Just the Way Nature Intended</h1><p class=\"nn-ah__sub\">At Namo Narayana, we believe good health begins with pure food. That belief inspired us to bring back the kind of desi ghee our grandparents trusted, made with patience, tradition, and honesty.</p><div class=\"nn-ah__intro\"><p>In a world full of shortcuts, we chose the longer path — because we believe purity is always worth the effort.</p></div></div>\n</section>\n\n<style>\n.nn-ah {\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  min-height: var(--nn-ah-height, 420px);\n  overflow: hidden;\n  background: #1a2e28;\n}\n.nn-ah__bg {\n  position: absolute; inset: 0;\n  width: 100%; height: 100%;\n  object-fit: cover;\n  display: block;\n}\nvideo.nn-ah__bg { object-position: center; }\n.nn-ah__overlay {\n  position: absolute; inset: 0;\n  background: var(--nn-ah-overlay);\n  opacity: var(--nn-ah-overlay-opacity);\n  pointer-events: none;\n}\n.nn-ah__content {\n  position: relative; z-index: 1;\n  text-align: center;\n  padding: 48px 24px;\n  max-width: 800px;\n}\n.nn-ah__eyebrow {\n  display: inline-flex; align-items: center; gap: 10px;\n  font-family: 'Figtree', system-ui, sans-serif;\n  font-size: 11px; font-weight: 700; letter-spacing: .16em;\n  text-transform: uppercase;\n  color: rgba(255,255,255,.7);\n  margin-bottom: 16px;\n}\n.nn-ah__eyebrow::before, .nn-ah__eyebrow::after {\n  content: ''; width: 28px; height: 1.5px; background: rgba(255,255,255,.35); border-radius: 2px;\n}\n.nn-ah__heading {\n  font-family: 'Fraunces', Georgia, serif;\n  font-size: clamp(32px, 5vw, 56px);\n  font-weight: 700;\n  color: #fff;\n  line-height: 1.12;\n  letter-spacing: -0.02em;\n  margin: 0 0 16px;\n}\n.nn-ah__sub {\n  font-family: 'Figtree', system-ui, sans-serif;\n  font-size: clamp(15px, 1.8vw, 19px);\n  font-weight: 400;\n  color: rgba(255,255,255,.8);\n  line-height: 1.65;\n  margin: 0;\n}\n.nn-ah__intro {\n  font-family: 'Figtree', system-ui, sans-serif;\n  font-size: clamp(14px, 1.5vw, 16px);\n  color: rgba(255,255,255,.7);\n  line-height: 1.7;\n  margin-top: 20px;\n  max-width: 640px;\n  margin-left: auto; margin-right: auto;\n}\n.nn-ah__intro p { margin: 0 0 10px; }\n.nn-ah__intro p:last-child { margin-bottom: 0; }\n@media (max-width: 600px) {\n  .nn-ah { min-height: calc(var(--nn-ah-height, 420px) * 0.65); }\n  .nn-ah__content { padding: 32px 16px; }\n}\n</style>\n\n\n</section><section id=\"shopify-section-template--21120678887592__about-story\" class=\"shopify-section\">\n\n<section class=\"nn-as\" id=\"nn-as-template--21120678887592__about-story\"><div class=\"nn-as__row\" style=\"background: #ffffff;\">\n      <div class=\"nn-as__inner\"><div class=\"nn-as__media\">\n            <video autoplay=\"\" muted=\"\" loop=\"\" playsinline=\"\" style=\"border-radius: 12px;\"><source src=\"//namonarayana.com/cdn/shop/videos/c/vp/e60e9e9216384286ad7445ea474c6420/e60e9e9216384286ad7445ea474c6420.m3u8?v=0\" type=\"application/x-mpegURL\"><source src=\"//namonarayana.com/cdn/shop/videos/c/vp/e60e9e9216384286ad7445ea474c6420/e60e9e9216384286ad7445ea474c6420.HD-1080p-7.2Mbps-90130411.mp4?v=0\" type=\"video/mp4\"></video>\n          </div><div class=\"nn-as__text\"><span class=\"nn-as__eyebrow\" style=\"color: #00584b;\">Our Heritage</span><h2 class=\"nn-as__heading\">Our Story</h2><div class=\"nn-as__body\"><p>For generations, ghee has been more than just food in Indian homes. It has been a part of our traditions, festivals, and everyday meals.</p><p>Over time, many products became commercial, losing the authentic taste and goodness that once made them special.</p><p>That's why Namo Narayana was created — to bring back real A2 Gir Cow Ghee made the traditional Bilona way, without compromising on quality or purity.</p></div></div>\n      </div>\n    </div><div class=\"nn-as__row nn-as__row--flip\" style=\"background: #fbf7ef;\">\n      <div class=\"nn-as__inner\"><div class=\"nn-as__media\">\n            <video autoplay=\"\" muted=\"\" loop=\"\" playsinline=\"\" style=\"border-radius: 12px;\"><source src=\"//namonarayana.com/cdn/shop/videos/c/vp/6833e2996ada44949fc45e2f9e31e885/6833e2996ada44949fc45e2f9e31e885.m3u8?v=0\" type=\"application/x-mpegURL\"><source src=\"//namonarayana.com/cdn/shop/videos/c/vp/6833e2996ada44949fc45e2f9e31e885/6833e2996ada44949fc45e2f9e31e885.HD-1080p-7.2Mbps-90001096.mp4?v=0\" type=\"video/mp4\"></video>\n          </div><div class=\"nn-as__text\"><span class=\"nn-as__eyebrow\" style=\"color: #00584b;\">Our Process</span><h2 class=\"nn-as__heading\">Made the Traditional Bilona Way</h2><div class=\"nn-as__body\"><p>Every jar of Namo Narayana Ghee starts with fresh A2 milk from indigenous Gir cows. The milk is naturally turned into curd, hand-churned using the traditional Bilona method, and slow-cooked to create rich, aromatic, golden ghee.</p><p>No shortcuts. No preservatives. No artificial additives. Just pure ghee, crafted with care.</p></div></div>\n      </div>\n    </div><div class=\"nn-as__row\" style=\"background: #ffffff;\">\n      <div class=\"nn-as__inner\"><div class=\"nn-as__media\">\n            <video autoplay=\"\" muted=\"\" loop=\"\" playsinline=\"\" style=\"border-radius: 12px;\"><source src=\"//namonarayana.com/cdn/shop/videos/c/vp/e4c552f4dca94ea5b1bc50e1e85bf5ea/e4c552f4dca94ea5b1bc50e1e85bf5ea.m3u8?v=0\" type=\"application/x-mpegURL\"><source src=\"//namonarayana.com/cdn/shop/videos/c/vp/e4c552f4dca94ea5b1bc50e1e85bf5ea/e4c552f4dca94ea5b1bc50e1e85bf5ea.HD-1080p-7.2Mbps-90001099.mp4?v=0\" type=\"video/mp4\"></video>\n          </div><div class=\"nn-as__text\"><span class=\"nn-as__eyebrow\" style=\"color: #00584b;\">Our Source</span><h2 class=\"nn-as__heading\">Pure from the Source</h2><div class=\"nn-as__body\"><p>Our Gir cows are raised with care and allowed to graze naturally. We use only A2 milk, known for its traditional nutritional value and wholesome goodness.</p><p>Every batch is carefully tested to ensure it meets the highest standards of quality before it reaches your home.</p></div></div>\n      </div>\n    </div><div class=\"nn-as__row nn-as__row--flip\" style=\"background: #fbf7ef;\">\n      <div class=\"nn-as__inner\"><div class=\"nn-as__media\">\n            <video autoplay=\"\" muted=\"\" loop=\"\" playsinline=\"\" style=\"border-radius: 12px;\"><source src=\"//namonarayana.com/cdn/shop/videos/c/vp/a8f6b141f4234fad853747e8a7b3a14a/a8f6b141f4234fad853747e8a7b3a14a.m3u8?v=0\" type=\"application/x-mpegURL\"><source src=\"//namonarayana.com/cdn/shop/videos/c/vp/a8f6b141f4234fad853747e8a7b3a14a/a8f6b141f4234fad853747e8a7b3a14a.HD-1080p-7.2Mbps-90019745.mp4?v=0\" type=\"video/mp4\"></video>\n          </div><div class=\"nn-as__text\"><span class=\"nn-as__eyebrow\" style=\"color: #00584b;\">Our Promise</span><h2 class=\"nn-as__heading\">More Than a Brand</h2><div class=\"nn-as__body\"><p>Namo Narayana is more than a ghee brand. It's our promise to bring honest, traditional food back to Indian kitchens.</p><p>Every product we make reflects one simple belief —</p><p><strong>If it isn't good enough for our own family, it isn't good enough for yours.</strong></p></div></div>\n      </div>\n    </div></section>\n\n<style>\n.nn-as__row { padding: 56px 24px; }\n.nn-as__inner {\n  max-width: 1140px; margin: 0 auto;\n  display: grid; grid-template-columns: 1fr 1fr;\n  gap: 48px; align-items: center;\n}\n.nn-as__row--flip .nn-as__inner { direction: rtl; }\n.nn-as__row--flip .nn-as__inner > * { direction: ltr; }\n.nn-as__media img, .nn-as__media video { width: 100%; height: auto; display: block; object-fit: cover; }\n.nn-as__eyebrow {\n  display: inline-flex; align-items: center; gap: 8px;\n  font-family: 'Figtree', system-ui, sans-serif;\n  font-size: 11px; font-weight: 700; letter-spacing: .14em;\n  text-transform: uppercase; margin-bottom: 12px;\n}\n.nn-as__eyebrow::before { content: ''; width: 24px; height: 2px; background: currentColor; border-radius: 2px; }\n.nn-as__heading {\n  font-family: 'Fraunces', Georgia, serif;\n  font-size: clamp(24px, 3.2vw, 36px); font-weight: 600;\n  color: #1a2e28; line-height: 1.2; letter-spacing: -.01em;\n  margin: 0 0 16px;\n}\n.nn-as__body {\n  font-family: 'Figtree', system-ui, sans-serif;\n  font-size: 15px; line-height: 1.75; color: #444;\n}\n.nn-as__body p { margin: 0 0 12px; }\n.nn-as__body p:last-child { margin-bottom: 0; }\n.nn-as__btn {\n  display: inline-block; margin-top: 20px;\n  padding: 12px 28px; border-radius: 8px;\n  font-family: 'Figtree', system-ui, sans-serif;\n  font-size: 14px; font-weight: 600; color: #fff;\n  text-decoration: none; transition: opacity .2s;\n}\n.nn-as__btn:hover { opacity: .88; }\n@media (max-width: 750px) {\n  .nn-as__inner { grid-template-columns: 1fr; gap: 28px; }\n  .nn-as__row--flip .nn-as__inner { direction: ltr; }\n  .nn-as__row { padding: 36px 16px; }\n}\n</style>\n\n\n</section><section id=\"shopify-section-template--21120678887592__about-values\" class=\"shopify-section\">\n\n<section class=\"nn-av\" id=\"nn-av-template--21120678887592__about-values\" style=\"background: #ffffff;\">\n  <div class=\"nn-av__wrap\"><div class=\"nn-av__header\"><span class=\"nn-av__eyebrow\">Our Promise</span><h2 class=\"nn-av__heading\">What Sets Us Apart</h2></div><div class=\"nn-av__grid nn-av__grid--4\"><div class=\"nn-av__card\"><div class=\"nn-av__emoji\">🐄</div><h3 class=\"nn-av__title\">Pure A2 Gir Cow Milk</h3><p class=\"nn-av__desc\">Sourced from indigenous Gir cows, raised on natural pastures with love and care.</p></div><div class=\"nn-av__card\"><div class=\"nn-av__emoji\">🧈</div><h3 class=\"nn-av__title\">Traditional Bilona Method</h3><p class=\"nn-av__desc\">Hand-churned from curd and slow-cooked the ancient way to preserve every nutrient.</p></div><div class=\"nn-av__card\"><div class=\"nn-av__emoji\">🌿</div><h3 class=\"nn-av__title\">100% Natural</h3><p class=\"nn-av__desc\">No additives, no preservatives, no artificial flavours — just pure, honest goodness.</p></div><div class=\"nn-av__card\"><div class=\"nn-av__emoji\">🔬</div><h3 class=\"nn-av__title\">Lab Tested &amp; Certified</h3><p class=\"nn-av__desc\">Every batch is rigorously tested to ensure purity, quality, and safety.</p></div></div></div>\n</section>\n\n<style>\n.nn-av { padding: 64px 24px; }\n.nn-av__wrap { max-width: 1140px; margin: 0 auto; }\n.nn-av__header { text-align: center; margin-bottom: 44px; }\n.nn-av__eyebrow {\n  display: inline-flex; align-items: center; gap: 10px;\n  font-family: 'Figtree', system-ui, sans-serif;\n  font-size: 11px; font-weight: 700; letter-spacing: .16em;\n  text-transform: uppercase; color: #00584B; margin-bottom: 10px;\n}\n.nn-av__eyebrow::before, .nn-av__eyebrow::after {\n  content: ''; width: 24px; height: 1.5px; background: #00584B; opacity: .4; border-radius: 2px;\n}\n.nn-av__heading {\n  font-family: 'Fraunces', Georgia, serif;\n  font-size: clamp(24px, 3.5vw, 38px); font-weight: 600;\n  color: #1a2e28; line-height: 1.18; margin: 0 0 12px;\n}\n.nn-av__sub {\n  font-family: 'Figtree', system-ui, sans-serif;\n  font-size: 15px; color: #666; line-height: 1.6; max-width: 560px; margin: 0 auto;\n}\n.nn-av__grid {\n  display: grid; gap: 28px;\n}\n.nn-av__grid--3 { grid-template-columns: repeat(3, 1fr); }\n.nn-av__grid--4 { grid-template-columns: repeat(4, 1fr); }\n.nn-av__grid--2 { grid-template-columns: repeat(2, 1fr); }\n.nn-av__card {\n  text-align: center; padding: 32px 20px;\n  background: #fff; border-radius: 14px;\n  border: 1px solid rgba(0,0,0,.06);\n  transition: box-shadow .25s, transform .25s;\n}\n.nn-av__card:hover { box-shadow: 0 8px 28px rgba(0,88,75,.08); transform: translateY(-3px); }\n.nn-av__icon img { width: 56px; height: 56px; object-fit: contain; margin: 0 auto 16px; display: block; }\n.nn-av__emoji { font-size: 40px; margin-bottom: 14px; line-height: 1; }\n.nn-av__title {\n  font-family: 'Fraunces', Georgia, serif;\n  font-size: 18px; font-weight: 600; color: #1a2e28;\n  margin: 0 0 8px; line-height: 1.3;\n}\n.nn-av__desc {\n  font-family: 'Figtree', system-ui, sans-serif;\n  font-size: 14px; color: #666; line-height: 1.65; margin: 0;\n}\n@media (max-width: 750px) {\n  .nn-av { padding: 40px 16px; }\n  .nn-av__grid--3, .nn-av__grid--4 { grid-template-columns: 1fr 1fr; }\n  .nn-av__card { padding: 24px 16px; }\n}\n@media (max-width: 450px) {\n  .nn-av__grid--2, .nn-av__grid--3, .nn-av__grid--4 { grid-template-columns: 1fr; }\n}\n</style>\n\n\n</section><section id=\"shopify-section-template--21120678887592__about-cta\" class=\"shopify-section\">\n\n<section class=\"nn-acta\" id=\"nn-acta-template--21120678887592__about-cta\" style=\"background: #00584b;\"><div class=\"nn-acta__content\"><h2 class=\"nn-acta__heading\" style=\"color: #ffffff;\">Namo Narayana</h2><p class=\"nn-acta__sub\" style=\"color: #ffffff;\">Pure by Promise. Traditional by Heart.</p><a href=\"\" class=\"nn-acta__btn\" style=\"background: #d4a853; color: #1a2e28;\">\n        Shop Now\n      </a></div>\n</section>\n\n<style>\n.nn-acta {\n  position: relative; overflow: hidden;\n  padding: 64px 24px; text-align: center;\n}\n.nn-acta__bg {\n  position: absolute; inset: 0;\n  width: 100%; height: 100%; object-fit: cover; display: block;\n}\n.nn-acta__overlay { position: absolute; inset: 0; pointer-events: none; }\n.nn-acta__content { position: relative; z-index: 1; max-width: 700px; margin: 0 auto; }\n.nn-acta__heading {\n  font-family: 'Fraunces', Georgia, serif;\n  font-size: clamp(24px, 4vw, 40px); font-weight: 700;\n  line-height: 1.18; margin: 0 0 14px;\n}\n.nn-acta__sub {\n  font-family: 'Figtree', system-ui, sans-serif;\n  font-size: 16px; line-height: 1.6; opacity: .85; margin: 0 0 28px;\n}\n.nn-acta__btn {\n  display: inline-block; padding: 14px 36px;\n  border-radius: 8px; font-family: 'Figtree', system-ui, sans-serif;\n  font-size: 15px; font-weight: 600; text-decoration: none;\n  transition: opacity .2s;\n}\n.nn-acta__btn:hover { opacity: .88; }\n@media (max-width: 600px) {\n  .nn-acta { padding: 44px 16px; }\n}\n</style>\n\n\n</section>\n    "},
  "careers": {"handle":"careers","seo":{"title":"Careers\n – Namo Narayana","description":"Join the Namo Narayana FamilyWe're building India's most trusted pure-food brand — and we're always looking for people who care about purity, tradition, and rural livelihoods.We hire across sourcing, quality, operations, marketing, and technology. If our mission speaks to you, write to us at namonarayanadev@gmail.com w","ogImage":""},"content":"\n      <section id=\"shopify-section-template--21006359625896__main\" class=\"shopify-section section\"><link href=\"//namonarayana.com/cdn/shop/t/8/assets/section-main-page.css?v=171954480266013350391783682218\" rel=\"stylesheet\" type=\"text/css\" media=\"all\">\n<style data-shopify=\"\">.section-template--21006359625896__main-padding {\n    padding-top: 27px;\n    padding-bottom: 21px;\n  }\n\n  @media screen and (min-width: 750px) {\n    .section-template--21006359625896__main-padding {\n      padding-top: 36px;\n      padding-bottom: 28px;\n    }\n  }</style><div class=\"page-width page-width--narrow section-template--21006359625896__main-padding\">\n  <h1 class=\"main-page-title page-title h0 scroll-trigger animate--fade-in\">\n    Careers\n  </h1>\n  <div class=\"rte scroll-trigger animate--slide-in\">\n    <h2>Join the Namo Narayana Family</h2><p>We're building India's most trusted pure-food brand — and we're always looking for people who care about purity, tradition, and rural livelihoods.</p><p>We hire across sourcing, quality, operations, marketing, and technology. If our mission speaks to you, write to us at <a href=\"mailto:namonarayanadev@gmail.com\">namonarayanadev@gmail.com</a> with your resume and a few lines about why you'd like to join.</p>\n  </div>\n</div>\n\n\n</section>\n    "},
  "certifications": {"handle":"certifications","seo":{"title":"Certifications\n – Namo Narayana","description":" Certified &amp; Approved Quality isn't a claim — it's a paper trail. Every Namo Narayana product is produced in certified facilities and tested in accredited labs. FSSAI — Licensed by India's food safety authority Batch-wise lab reports are available on request — write to us anytime. Batch No. = NMO-260722-A0 - Get Re","ogImage":""},"content":"\n      <section id=\"shopify-section-template--21006359625896__main\" class=\"shopify-section section\"><link href=\"//namonarayana.com/cdn/shop/t/8/assets/section-main-page.css?v=171954480266013350391783682218\" rel=\"stylesheet\" type=\"text/css\" media=\"all\">\n<style data-shopify=\"\">.section-template--21006359625896__main-padding {\n    padding-top: 27px;\n    padding-bottom: 21px;\n  }\n\n  @media screen and (min-width: 750px) {\n    .section-template--21006359625896__main-padding {\n      padding-top: 36px;\n      padding-bottom: 28px;\n    }\n  }</style><div class=\"page-width page-width--narrow section-template--21006359625896__main-padding\">\n  <h1 class=\"main-page-title page-title h0 scroll-trigger animate--fade-in\">\n    Certifications\n  </h1>\n  <div class=\"rte scroll-trigger animate--slide-in\">\n    <h2>&nbsp;Certified &amp; Approved</h2>\n<p>Quality isn't a claim — it's a paper trail. Every Namo Narayana product is produced in certified facilities and tested in accredited labs.<strong></strong></p>\n<ul>\n<li>\n<strong>FSSAI</strong> — <a href=\"https://cdn.shopify.com/s/files/1/0758/0490/1544/files/o_f20260715-011-015_2.pdf?v=1785484275\">Licensed by India's food safety authority</a><strong></strong>\n</li>\n</ul>\n<p>Batch-wise lab reports are available on request — write to us anytime.</p>\n<p>Batch No. = <a href=\"https://cdn.shopify.com/s/files/1/0758/0490/1544/files/o_f20260715-011-015_2.pdf?v=1785484275\" title=\"Lab Report Namo Narayana\">NMO-260722-A0 - Get Report</a></p>\n<p><img src=\"https://cdn.shopify.com/s/files/1/0758/0490/1544/files/IMG-20260728-WA0131_jpg_b04570c5-92c7-4348-90a9-11972108ad9b.webp?v=1785769477\" alt=\"\"></p>\n  </div>\n</div>\n\n\n</section>\n    "},
  "contact": {"handle":"contact","seo":{"title":"Contact\n – Namo Narayana","description":"Get in Touch We'd love to hear from you! Whether you have a question about our products, need help with an order, or just want to say hello — we're here for you. Customer Support Email: namonarayanadev@gmail.com Response Time: We typically respond within 24 hours (Mon–Sat, 10 AM – 7 PM IST) Order Related Queries For qu","ogImage":""},"content":"\n      <section id=\"shopify-section-template--21006359167144__main\" class=\"shopify-section section\"><link href=\"//namonarayana.com/cdn/shop/t/8/assets/section-main-page.css?v=171954480266013350391783682218\" rel=\"stylesheet\" type=\"text/css\" media=\"all\">\n<style data-shopify=\"\">.section-template--21006359167144__main-padding {\n    padding-top: 27px;\n    padding-bottom: 0px;\n  }\n\n  @media screen and (min-width: 750px) {\n    .section-template--21006359167144__main-padding {\n      padding-top: 36px;\n      padding-bottom: 0px;\n    }\n  }</style><div class=\"page-width page-width--narrow section-template--21006359167144__main-padding\">\n  <h1 class=\"main-page-title page-title h0 scroll-trigger animate--fade-in\">\n    Contact\n  </h1>\n  <div class=\"rte scroll-trigger animate--slide-in\">\n    <h2>Get in Touch</h2>\n<p>We'd love to hear from you! Whether you have a question about our products, need help with an order, or just want to say hello — we're here for you.</p>\n<h3>Customer Support</h3>\n<ul>\n<li>\n<strong>Email:</strong> <a href=\"mailto:namonarayanadev@gmail.com\">namonarayanadev@gmail.com</a>\n</li>\n<li>\n<strong>Response Time:</strong> We typically respond within 24 hours (Mon–Sat, 10 AM – 7 PM IST)</li>\n</ul>\n<h3>Order Related Queries</h3>\n<p>For questions about your order status, shipping, returns, or refunds, please email us with your <strong>Order ID</strong> and we'll get back to you promptly.</p>\n<h3>Business &amp; Partnerships</h3>\n<p>For bulk orders, wholesale enquiries, collaborations, or media requests, write to us at <a href=\"mailto:namonarayanadev@gmail.com\">namonarayanadev@gmail.com</a> with the subject line \"Business Enquiry\".</p>\n<h3>Registered Office</h3>\n<p><strong>Namo Narayana</strong><br>India</p>\n<h3>Grievance Officer</h3>\n<p>In accordance with the Consumer Protection (E-Commerce) Rules, 2020, the details of our Grievance Officer are as follows:</p>\n<ul>\n<li>\n<strong>Name:</strong> Namo Narayana</li>\n<li>\n<strong>Email:</strong> <a href=\"mailto:namonarayanadev@gmail.com\">namonarayanadev@gmail.com</a>\n</li>\n<li>\n<strong>Response Time:</strong> All grievances will be acknowledged within 48 hours and resolved within 30 days.</li>\n</ul>\n  </div>\n</div>\n\n\n</section><section id=\"shopify-section-template--21006359167144__form\" class=\"shopify-section section\"><link href=\"//namonarayana.com/cdn/shop/t/8/assets/section-contact-form.css?v=49807578925852721501783682229\" rel=\"stylesheet\" type=\"text/css\" media=\"all\">\n<style data-shopify=\"\">.section-template--21006359167144__form-padding {\n    padding-top: 0px;\n    padding-bottom: 45px;\n  }\n\n  @media screen and (min-width: 750px) {\n    .section-template--21006359167144__form-padding {\n      padding-top: 0px;\n      padding-bottom: 60px;\n    }\n  }</style><div class=\"color-scheme-1 gradient\">\n  <div class=\"contact page-width page-width--narrow section-template--21006359167144__form-padding\"><h2 class=\"visually-hidden\">Contact form</h2><form method=\"post\" action=\"/contact#ContactForm\" id=\"ContactForm\" accept-charset=\"UTF-8\" class=\"isolate scroll-trigger animate--slide-in\"><input type=\"hidden\" name=\"form_type\" value=\"contact\"><input type=\"hidden\" name=\"utf8\" value=\"✓\"><div class=\"contact__fields\">\n        <div class=\"field\">\n          <input class=\"field__input\" autocomplete=\"name\" type=\"text\" id=\"ContactForm-name\" name=\"contact[Name]\" value=\"\" placeholder=\"Name\">\n          <label class=\"field__label\" for=\"ContactForm-name\">Name</label>\n        </div>\n        <div class=\"field field--with-error\">\n          <input autocomplete=\"email\" type=\"email\" id=\"ContactForm-email\" class=\"field__input\" name=\"contact[email]\" spellcheck=\"false\" autocapitalize=\"off\" value=\"\" aria-required=\"true\" placeholder=\"Email\">\n          <label class=\"field__label\" for=\"ContactForm-email\">Email\n            <span aria-hidden=\"true\">*</span></label></div>\n      </div>\n      <div class=\"field\">\n        <input type=\"tel\" id=\"ContactForm-phone\" class=\"field__input\" autocomplete=\"tel\" name=\"contact[Phone number]\" pattern=\"[0-9\\-]*\" value=\"\" placeholder=\"Phone number\">\n        <label class=\"field__label\" for=\"ContactForm-phone\">Phone number</label>\n      </div>\n      <div class=\"field\">\n        <textarea rows=\"10\" id=\"ContactForm-body\" class=\"text-area field__input\" name=\"contact[Comment]\" placeholder=\"Comment\"></textarea>\n        <label class=\"form__label field__label\" for=\"ContactForm-body\">Comment</label>\n      </div>\n      <div class=\"contact__button\">\n        <button type=\"submit\" class=\"button\">\n          Send\n        </button>\n      </div></form></div>\n</div>\n\n\n</section>\n    "},
  "farm-to-fork": {"handle":"farm-to-fork","seo":{"title":"Farm to Fork\n – Namo Narayana","description":"The Journey of Every JarEvery Namo Narayana product travels a carefully guarded path from farm to your family's plate.1. Native SourcingWe source from indigenous farms in each ingredient's original growing region — the right soil, altitude, and season.2. Traditional ProcessingBilona churning for ghee, wooden cold-press","ogImage":""},"content":"\n      <section id=\"shopify-section-template--21006359625896__main\" class=\"shopify-section section\"><link href=\"//namonarayana.com/cdn/shop/t/8/assets/section-main-page.css?v=171954480266013350391783682218\" rel=\"stylesheet\" type=\"text/css\" media=\"all\">\n<style data-shopify=\"\">.section-template--21006359625896__main-padding {\n    padding-top: 27px;\n    padding-bottom: 21px;\n  }\n\n  @media screen and (min-width: 750px) {\n    .section-template--21006359625896__main-padding {\n      padding-top: 36px;\n      padding-bottom: 28px;\n    }\n  }</style><div class=\"page-width page-width--narrow section-template--21006359625896__main-padding\">\n  <h1 class=\"main-page-title page-title h0 scroll-trigger animate--fade-in\">\n    Farm to Fork\n  </h1>\n  <div class=\"rte scroll-trigger animate--slide-in\">\n    <h2>The Journey of Every Jar</h2><p>Every Namo Narayana product travels a carefully guarded path from farm to your family's plate.</p><h3>1. Native Sourcing</h3><p>We source from indigenous farms in each ingredient's original growing region — the right soil, altitude, and season.</p><h3>2. Traditional Processing</h3><p>Bilona churning for ghee, wooden cold-pressing for oils, stone grinding for flours. Slow methods that preserve nutrition.</p><h3>3. Three Layers of Testing</h3><p>Every batch is tested at sourcing, during processing, and before packaging — 40+ lab checks for purity, adulteration, and nutrition.</p><h3>4. Fresh to Your Door</h3><p>Small batches, sealed at source, and shipped across India in secure packaging within days of production.</p>\n  </div>\n</div>\n\n\n</section>\n    "},
  "our-story": {"handle":"our-story","seo":{"title":"Our Story\n – Namo Narayana","description":"From India's Heartland to Your HomeNamo Narayana began with a simple belief: food should be as pure as it was in our grandparents' kitchens. We work directly with 5000+ farmer families across India's native regions to bring you ghee, oils, honey and more — made the traditional way, tested in certified labs, and deliver","ogImage":""},"content":"\n      <section id=\"shopify-section-template--21006359625896__main\" class=\"shopify-section section\"><link href=\"//namonarayana.com/cdn/shop/t/8/assets/section-main-page.css?v=171954480266013350391783682218\" rel=\"stylesheet\" type=\"text/css\" media=\"all\">\n<style data-shopify=\"\">.section-template--21006359625896__main-padding {\n    padding-top: 27px;\n    padding-bottom: 21px;\n  }\n\n  @media screen and (min-width: 750px) {\n    .section-template--21006359625896__main-padding {\n      padding-top: 36px;\n      padding-bottom: 28px;\n    }\n  }</style><div class=\"page-width page-width--narrow section-template--21006359625896__main-padding\">\n  <h1 class=\"main-page-title page-title h0 scroll-trigger animate--fade-in\">\n    Our Story\n  </h1>\n  <div class=\"rte scroll-trigger animate--slide-in\">\n    <h2>From India's Heartland to Your Home</h2><p>Namo Narayana began with a simple belief: food should be as pure as it was in our grandparents' kitchens. We work directly with 5000+ farmer families across India's native regions to bring you ghee, oils, honey and more — made the traditional way, tested in certified labs, and delivered with zero preservatives.</p><h3>Our Promise</h3><ul>\n<li>Native ingredients sourced from their original growing regions</li>\n<li>Traditional processing — Bilona churned, cold pressed, stone ground</li>\n<li>40+ quality checks on every single batch</li>\n<li>Fair prices that empower rural farming families</li>\n</ul><p><em>Not high yield. Not lower cost. Just flavour, nutrition, and soul.</em></p>\n  </div>\n</div>\n\n\n</section>\n    "},
  "social-media": {"handle":"social-media","seo":{"title":"Social Media\n – Namo Narayana","description":"","ogImage":""},"content":"\n      <section id=\"shopify-section-template--21006359265448__social\" class=\"shopify-section nn-social-section\">\n\n<section class=\"nn-social\" id=\"nn-social-template--21006359265448__social\"><div class=\"nn-social__container\"><div class=\"nn-social__logo-wrap\">\n        <div class=\"nn-social__logo-ring\">\n          <img src=\"//namonarayana.com/cdn/shop/files/Namo_Narayana_Officail_Logo.png?v=1783232358&amp;width=300\" alt=\"Namo Narayana\" class=\"nn-social__logo\" width=\"120\" height=\"120\" loading=\"eager\">\n        </div>\n      </div><div class=\"nn-social__header nn-social__header--center\"><p class=\"nn-social__eyebrow\">\n          <span class=\"nn-social__eyebrow-line\"></span>\n          Stay Connected\n          <span class=\"nn-social__eyebrow-line\"></span>\n        </p><h1 class=\"nn-social__heading\">Follow Namo Narayana</h1><p class=\"nn-social__subheading\">Join our community for updates, offers and behind-the-scenes content</p></div><div class=\"nn-social__grid\"><a href=\"https://www.instagram.com/namonarayanaofficial?igsh=eDgxdWlvajJ4NnVy\" class=\"nn-social__card\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Instagram\" data-platform=\"instagram\">\n            <span class=\"nn-social__icon-wrap nn-social__icon-wrap--custom\"><img src=\"//namonarayana.com/cdn/shop/files/insta.png?v=1783231559&amp;width=120\" alt=\"\" class=\"nn-social__icon nn-social__icon--custom\" width=\"52\" height=\"52\" loading=\"lazy\"></span>\n\n            <span class=\"nn-social__text\">\n              <span class=\"nn-social__label\">Instagram</span></span>\n\n            <span class=\"nn-social__arrow\" aria-hidden=\"true\">\n              <svg viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n                <path d=\"M9 6l6 6-6 6\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path>\n              </svg>\n            </span>\n          </a><a href=\"https://www.facebook.com/share/18hvKbVSpg/\" class=\"nn-social__card\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Facebook\" data-platform=\"facebook\">\n            <span class=\"nn-social__icon-wrap nn-social__icon-wrap--custom\"><img src=\"//namonarayana.com/cdn/shop/files/fb.png?v=1783231558&amp;width=120\" alt=\"\" class=\"nn-social__icon nn-social__icon--custom\" width=\"52\" height=\"52\" loading=\"lazy\"></span>\n\n            <span class=\"nn-social__text\">\n              <span class=\"nn-social__label\">Facebook</span></span>\n\n            <span class=\"nn-social__arrow\" aria-hidden=\"true\">\n              <svg viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n                <path d=\"M9 6l6 6-6 6\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path>\n              </svg>\n            </span>\n          </a><a href=\"https://youtube.com/@namonarayanaofficial?si=nJeKiiTTczsHWFnd\" class=\"nn-social__card\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Youtube\" data-platform=\"youtube\">\n            <span class=\"nn-social__icon-wrap nn-social__icon-wrap--custom\"><img src=\"//namonarayana.com/cdn/shop/files/yt.png?v=1783231558&amp;width=120\" alt=\"\" class=\"nn-social__icon nn-social__icon--custom\" width=\"52\" height=\"52\" loading=\"lazy\"></span>\n\n            <span class=\"nn-social__text\">\n              <span class=\"nn-social__label\">Youtube</span></span>\n\n            <span class=\"nn-social__arrow\" aria-hidden=\"true\">\n              <svg viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n                <path d=\"M9 6l6 6-6 6\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path>\n              </svg>\n            </span>\n          </a><a href=\"https://x.com/thenamonarayana\" class=\"nn-social__card\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"X (Twitter)\" data-platform=\"x\">\n            <span class=\"nn-social__icon-wrap nn-social__icon-wrap--custom\"><img src=\"//namonarayana.com/cdn/shop/files/x_logo.png?v=1783231558&amp;width=120\" alt=\"\" class=\"nn-social__icon nn-social__icon--custom\" width=\"52\" height=\"52\" loading=\"lazy\"></span>\n\n            <span class=\"nn-social__text\">\n              <span class=\"nn-social__label\">X (Twitter)</span></span>\n\n            <span class=\"nn-social__arrow\" aria-hidden=\"true\">\n              <svg viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n                <path d=\"M9 6l6 6-6 6\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path>\n              </svg>\n            </span>\n          </a></div></div>\n</section>\n\n<style>\n  @font-face {\n  font-family: Fraunces;\n  font-weight: 700;\n  font-style: normal;\n  font-display: swap;\n  src: url(\"//namonarayana.com/cdn/fonts/fraunces/fraunces_n7.8276f3981cfafc8569d516ceaa7dfe6a18948a1f.woff2\") format(\"woff2\"),\n       url(\"//namonarayana.com/cdn/fonts/fraunces/fraunces_n7.383b2f958615709ba42e3731be308ad164ca4edd.woff\") format(\"woff\");\n}\n\n  @font-face {\n  font-family: Figtree;\n  font-weight: 400;\n  font-style: normal;\n  font-display: swap;\n  src: url(\"//namonarayana.com/cdn/fonts/figtree/figtree_n4.3c0838aba1701047e60be6a99a1b0a40ce9b8419.woff2\") format(\"woff2\"),\n       url(\"//namonarayana.com/cdn/fonts/figtree/figtree_n4.c0575d1db21fc3821f17fd6617d3dee552312137.woff\") format(\"woff\");\n}\n\n\n  .nn-social {\n    --nn-primary: #00584B;\n    --nn-primary-dark: #003F36;\n    --nn-green-tint: #EAF1ED;\n    --nn-bg-warm: #FBF7EF;\n    --nn-text: #242424;\n    --nn-text-light: #5C6B65;\n    --nn-hairline: #E7E1D5;\n    --nn-social-heading-color: #242424;\n    --nn-social-subheading-color: #5C6B65;\n    --nn-social-eyebrow-color: #00584B;\n    --nn-social-container: 620px;\n    --nn-social-heading-size: 44px;\n    position: relative;\n    isolation: isolate;\n    min-height: 100vh;\n    overflow: hidden;\n    background: #f9f6ef;\n    padding: 60px 0 60px;\n    margin: 0px 0 0px;\n    font-family: Figtree, sans-serif;\n    display: flex;\n    align-items: center;\n  }\n\n  /* Real <img> background — renders SVG-with-embedded-images on iOS/mobile (CSS background-image does not) + overlay */.nn-social__container {\n    position: relative;\n    z-index: 1;\n    max-width: var(--nn-social-container, 620px);\n    margin: 0 auto;\n    padding: 0 24px;\n    width: 100%;\n  }\n\n  /* Logo */\n  .nn-social__logo-wrap {\n    display: flex;\n    justify-content: center;\n    margin-bottom: 26px;\n  }\n  .nn-social__logo-ring {\n    width: 116px;\n    height: 116px;\n    border-radius: 50%;\n    padding: 5px;\n    background: #FFFFFF;\n    border: 1px solid var(--nn-hairline);\n    box-shadow: 0 1px 3px rgba(36,36,36,.06);\n  }\n  .nn-social__logo {\n    width: 100%;\n    height: 100%;\n    border-radius: 50%;\n    object-fit: cover;\n    display: block;\n    background: #fff;\n  }\n\n  /* Header */\n  .nn-social__header {\n    text-align: center;\n    margin-bottom: 40px;\n  }\n  .nn-social__header--left   { text-align: left; }\n  .nn-social__header--center { text-align: center; }\n  .nn-social__header--right  { text-align: right; }\n  .nn-social__header--left   .nn-social__eyebrow { justify-content: flex-start; }\n  .nn-social__header--right  .nn-social__eyebrow { justify-content: flex-end; }\n  .nn-social__header--left   .nn-social__subheading { margin-inline: 0; }\n  .nn-social__header--right  .nn-social__subheading { margin-left: auto; margin-right: 0; }\n  .nn-social__eyebrow {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    gap: 10px;\n    font-size: 11px;\n    font-weight: 700;\n    letter-spacing: .18em;\n    text-transform: uppercase;\n    color: var(--nn-social-eyebrow-color, #00584B);\n    margin: 0 0 14px;\n  }\n  .nn-social__eyebrow-line {\n    width: 28px;\n    height: 1px;\n    background: var(--nn-hairline);\n  }\n\n  .nn-social__heading {\n    font-family: Fraunces, serif;\n    font-size: clamp(30px, 5vw, var(--nn-social-heading-size, 44px));\n    font-weight: 700;\n    color: var(--nn-social-heading-color, #242424);\n    margin: 0 0 12px;\n    line-height: 1.18;\n    letter-spacing: -.01em;\n  }\n  .nn-social__subheading {\n    font-size: 15px;\n    line-height: 1.6;\n    color: var(--nn-social-subheading-color, #5C6B65);\n    margin: 0;\n    max-width: 440px;\n    margin-inline: auto;\n  }\n\n  /* Cards */\n  .nn-social__grid {\n    display: flex;\n    flex-direction: column;\n    gap: 14px;\n  }\n\n  .nn-social__card {\n    position: relative;\n    display: flex;\n    align-items: center;\n    gap: 16px;\n    padding: 18px 22px;\n    background: #FFFFFF;\n    border-radius: 12px;\n    border: 1px solid var(--nn-hairline);\n    text-decoration: none;\n    box-shadow: 0 1px 3px rgba(36,36,36,.06);\n    transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;\n  }\n  .nn-social__card:hover {\n    transform: translateY(-3px);\n    box-shadow: 0 8px 22px rgba(36,36,36,.10);\n    border-color: var(--nn-primary);\n  }\n  .nn-social__card:active { transform: translateY(-1px); }\n\n  .nn-social__icon-wrap {\n    flex-shrink: 0;\n    width: 48px;\n    height: 48px;\n    border-radius: 12px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    background: var(--nn-primary);\n    color: #fff;\n    transition: background .25s ease;\n  }\n  .nn-social__card:hover .nn-social__icon-wrap {\n    background: var(--nn-primary-dark);\n  }\n  /* Custom uploaded icons — no colored box, just the image, same size for all */\n  .nn-social__icon-wrap--custom {\n    background: none;\n    box-shadow: none;\n    width: 52px;\n    height: 52px;\n  }\n  .nn-social__card:hover .nn-social__icon-wrap--custom {\n    background: none;\n  }\n  .nn-social__icon { width: 22px; height: 22px; }\n  .nn-social__icon--custom {\n    width: 52px;\n    height: 52px;\n    object-fit: contain;\n  }\n\n  .nn-social__text {\n    flex: 1;\n    min-width: 0;\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n    gap: 3px;\n  }\n  .nn-social__label {\n    font-size: 19px;\n    font-weight: 700;\n    color: var(--nn-text);\n  }\n  .nn-social__handle {\n    font-size: 13px;\n    color: var(--nn-text-light);\n  }\n\n  .nn-social__arrow {\n    flex-shrink: 0;\n    color: var(--nn-text-light);\n    opacity: 0;\n    transform: translateX(-6px);\n    transition: opacity .3s ease, transform .3s ease, color .3s ease;\n  }\n  .nn-social__arrow svg { width: 18px; height: 18px; }\n  .nn-social__card:hover .nn-social__arrow {\n    opacity: 1;\n    transform: translateX(0);\n    color: var(--nn-primary);\n  }\n\n  /* Scroll reveal */\n  @media (prefers-reduced-motion: no-preference) {\n    .nn-social__card {\n      opacity: 0;\n      transform: translateY(18px);\n      animation: nn-social-fade-in .6s cubic-bezier(.22,1,.36,1) forwards;\n    }\n    .nn-social__card:nth-child(1) { animation-delay: .05s; }\n    .nn-social__card:nth-child(2) { animation-delay: .12s; }\n    .nn-social__card:nth-child(3) { animation-delay: .19s; }\n    .nn-social__card:nth-child(4) { animation-delay: .26s; }\n    .nn-social__card:nth-child(5) { animation-delay: .33s; }\n    .nn-social__card:nth-child(6) { animation-delay: .4s; }\n    @keyframes nn-social-fade-in {\n      to { opacity: 1; transform: translateY(0); }\n    }\n  }\n\n  .nn-social__footer-text {\n    text-align: center;\n    margin: 36px 0 0;\n    font-size: 13px;\n    color: var(--nn-text-light);\n  }\n\n  @media (max-width: 480px) {\n    .nn-social { padding: 56px 0; }\n    .nn-social__card { padding: 15px 16px; gap: 13px; }\n    .nn-social__icon-wrap { width: 42px; height: 42px; border-radius: 12px; }\n    .nn-social__icon-wrap--custom { width: 42px; height: 42px; }\n    .nn-social__icon { width: 19px; height: 19px; }\n    .nn-social__icon--custom { width: 42px; height: 42px; }\n    .nn-social__label { font-size: 16px; }\n  }\n</style>\n\n\n</section>\n    "},
  "track-order": {"handle":"track-order","seo":{"title":"Track Order\n – Namo Narayana","description":"Namo Narayana","ogImage":""},"content":"\n      <section id=\"shopify-section-template--21161880158376__track-order\" class=\"shopify-section nn-track-section\">\n\n<div class=\"nn-ds-section nn-ds-section--cream nn-track\">\n  <div class=\"nn-ds-container\">\n    <div class=\"nn-track__card nn-ds-card\" id=\"nn-track-form\">\n      <div class=\"nn-track__card-inner\">\n        <h1 class=\"nn-ds-title\" style=\"text-align:center;\">Track Your Order</h1>\n        <p class=\"nn-ds-sub\" style=\"text-align:center;margin-top:8px;\">\n          Enter your Order ID or AWB number to check shipment status.\n        </p>\n\n        <div class=\"nn-track__toggle\">\n          <label class=\"nn-track__radio is-active\" data-mode=\"order_id\">\n            <input type=\"radio\" name=\"trackMode\" value=\"order_id\" checked=\"\">\n            <span>Order ID</span>\n          </label>\n          <label class=\"nn-track__radio\" data-mode=\"awb\">\n            <input type=\"radio\" name=\"trackMode\" value=\"awb\">\n            <span>Tracking ID / AWB</span>\n          </label>\n        </div>\n\n        <div class=\"nn-track__search\">\n          <input type=\"text\" id=\"nn-track-input\" class=\"nn-track__input\" placeholder=\"Enter your Order ID\" autocomplete=\"off\">\n          <button class=\"nn-ds-btn nn-ds-btn--primary nn-track__btn\" id=\"nn-track-btn\">\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line></svg>\n            Track\n          </button>\n        </div>\n\n        <p class=\"nn-track__msg\" id=\"nn-track-msg\"></p>\n      </div>\n    </div>\n    <div class=\"nn-track__result\" id=\"nn-track-result\" style=\"display:none;\">\n      <button class=\"nn-track__back\" id=\"nn-track-back\">\n        <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"19\" y1=\"12\" x2=\"5\" y2=\"12\"></line><polyline points=\"12 19 5 12 12 5\"></polyline></svg>\n        Track Another Order\n      </button>\n      <div class=\"nn-track__status-card nn-ds-card\" id=\"nn-track-status\"></div>\n      <div class=\"nn-track__timeline-card nn-ds-card\" id=\"nn-track-timeline\"></div>\n      <div class=\"nn-track__activity-card nn-ds-card\" id=\"nn-track-activity\">\n        <button class=\"nn-track__activity-toggle\" id=\"nn-track-activity-toggle\">\n          <span>Shipment Activity</span>\n          <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"></polyline></svg>\n        </button>\n        <div class=\"nn-track__activity-list\" id=\"nn-track-activity-list\" style=\"display:none;\"></div>\n      </div>\n    </div>\n\n  </div>\n</div>\n\n<style>\n  /* ── Track Section ── */\n  .nn-track { min-height: 60vh; display:flex; align-items:flex-start; }\n\n  .nn-track__card { max-width:600px; margin:0 auto; overflow:hidden; }\n  .nn-track__card-inner { padding: clamp(24px,4vw,40px); }\n\n  /* Toggle */\n  .nn-track__toggle { display:flex; gap:8px; justify-content:center; margin:24px 0 20px; }\n  .nn-track__radio { display:flex; align-items:center; gap:6px; padding:8px 16px; border-radius:var(--nn-radius-sm); border:1.5px solid var(--nn-hairline); cursor:pointer; font-family:var(--nn-font-body); font-size:.875rem; font-weight:600; color:var(--nn-bark); transition:all .2s ease; }\n  .nn-track__radio:hover { border-color:var(--nn-leaf); }\n  .nn-track__radio.is-active { background:var(--nn-leaf); color:#fff; border-color:var(--nn-leaf); }\n  .nn-track__radio input { display:none; }\n\n  /* Search */\n  .nn-track__search { display:flex; gap:8px; }\n  .nn-track__input { flex:1; font-family:var(--nn-font-body); font-size:1rem; padding:12px 16px; border:1.5px solid var(--nn-hairline); border-radius:var(--nn-radius-sm); background:var(--nn-white); color:var(--nn-ink); outline:none; transition:border-color .2s; }\n  .nn-track__input:focus { border-color:var(--nn-leaf); }\n  .nn-track__btn { white-space:nowrap; }\n  .nn-track__msg { font-family:var(--nn-font-body); font-size:.875rem; margin-top:12px; text-align:center; min-height:20px; }\n  .nn-track__msg--error { color:#c0392b; }\n  .nn-track__msg--loading { color:var(--nn-bark); }\n\n  /* Loader */\n  .nn-track__loader { display:inline-block; width:18px; height:18px; border:2.5px solid var(--nn-hairline); border-top-color:var(--nn-leaf); border-radius:50%; animation:nn-spin .6s linear infinite; vertical-align:middle; margin-right:6px; }\n  @keyframes nn-spin { to { transform:rotate(360deg); } }\n\n  /* Back */\n  .nn-track__back { display:inline-flex; align-items:center; gap:6px; font-family:var(--nn-font-body); font-size:.875rem; font-weight:600; color:var(--nn-leaf); background:none; border:none; cursor:pointer; padding:0; margin-bottom:16px; }\n  .nn-track__back:hover { color:var(--nn-leaf-hover); }\n\n  /* Status card */\n  .nn-track__status-card { padding:clamp(20px,3vw,32px); margin-bottom:16px; }\n  .nn-track__status-top { display:flex; align-items:center; gap:12px; margin-bottom:16px; }\n  .nn-track__status-icon { width:48px; height:48px; border-radius:50%; display:flex; align-items:center; justify-content:center; flex-shrink:0; }\n  .nn-track__status-icon--green { background:#E8F5E9; color:#2E7D32; }\n  .nn-track__status-icon--blue { background:#E3F2FD; color:#1565C0; }\n  .nn-track__status-icon--orange { background:#FFF3E0; color:#E65100; }\n  .nn-track__status-label { font-family:var(--nn-font-head); font-size:clamp(1.25rem,1rem+1vw,1.5rem); font-weight:600; color:var(--nn-ink); }\n  .nn-track__status-sub { font-family:var(--nn-font-body); font-size:.8125rem; color:var(--nn-bark); }\n  .nn-track__info-row { display:flex; flex-wrap:wrap; gap:12px 24px; padding-top:16px; border-top:1px solid var(--nn-hairline); }\n  .nn-track__info-item { font-family:var(--nn-font-body); font-size:.8125rem; }\n  .nn-track__info-item span:first-child { color:var(--nn-bark); }\n  .nn-track__info-item span:last-child { font-weight:600; color:var(--nn-ink); margin-left:4px; }\n\n  /* Timeline */\n  .nn-track__timeline-card { padding:clamp(20px,3vw,32px); margin-bottom:16px; }\n  .nn-track__steps { display:flex; justify-content:space-between; position:relative; }\n  .nn-track__steps::before { content:''; position:absolute; top:18px; left:24px; right:24px; height:3px; background:var(--nn-hairline); z-index:0; }\n  .nn-track__progress-bar { position:absolute; top:18px; left:24px; height:3px; background:var(--nn-leaf); z-index:1; transition:width .5s ease; }\n  .nn-track__step { display:flex; flex-direction:column; align-items:center; gap:8px; position:relative; z-index:2; flex:1; }\n  .nn-track__step-dot { width:36px; height:36px; border-radius:50%; border:3px solid var(--nn-hairline); background:var(--nn-white); display:flex; align-items:center; justify-content:center; transition:all .3s ease; }\n  .nn-track__step.is-done .nn-track__step-dot { background:var(--nn-leaf); border-color:var(--nn-leaf); }\n  .nn-track__step.is-current .nn-track__step-dot { border-color:var(--nn-leaf); background:var(--nn-white); box-shadow:0 0 0 4px rgba(35,90,73,.15); }\n  .nn-track__step-label { font-family:var(--nn-font-body); font-size:.7rem; font-weight:600; color:var(--nn-bark); text-align:center; max-width:72px; line-height:1.3; }\n  .nn-track__step.is-done .nn-track__step-label,\n  .nn-track__step.is-current .nn-track__step-label { color:var(--nn-ink); }\n  .nn-track__step-date { font-family:var(--nn-font-body); font-size:.65rem; color:var(--nn-bark); text-align:center; }\n\n  /* Activity */\n  .nn-track__activity-card { overflow:hidden; }\n  .nn-track__activity-toggle { width:100%; display:flex; align-items:center; justify-content:space-between; padding:16px clamp(20px,3vw,32px); background:none; border:none; cursor:pointer; font-family:var(--nn-font-body); font-size:.9375rem; font-weight:700; color:var(--nn-ink); }\n  .nn-track__activity-toggle svg { transition:transform .2s; }\n  .nn-track__activity-toggle.is-open svg { transform:rotate(180deg); }\n  .nn-track__activity-list { padding:0 clamp(20px,3vw,32px) 20px; }\n  .nn-track__activity-item { display:flex; gap:12px; padding:10px 0; border-bottom:1px solid var(--nn-hairline); }\n  .nn-track__activity-item:last-child { border-bottom:none; }\n  .nn-track__activity-dot { width:8px; height:8px; border-radius:50%; background:var(--nn-leaf); margin-top:6px; flex-shrink:0; }\n  .nn-track__activity-text { font-family:var(--nn-font-body); font-size:.8125rem; color:var(--nn-ink); line-height:1.5; }\n  .nn-track__activity-meta { font-size:.75rem; color:var(--nn-bark); margin-top:2px; }\n\n  /* Result area */\n  .nn-track__result { max-width:600px; margin:0 auto; }\n\n  @media(max-width:600px){\n    .nn-track__search { flex-direction:column; }\n    .nn-track__toggle { flex-direction:column; align-items:stretch; }\n    .nn-track__step-label { font-size:.6rem; max-width:56px; }\n    .nn-track__step-dot { width:28px; height:28px; }\n    .nn-track__steps::before { top:14px; left:16px; right:16px; }\n    .nn-track__progress-bar { top:14px; left:16px; }\n    .nn-track__info-row { flex-direction:column; gap:8px; }\n  }\n</style>\n\n<script>\n  (function(){\n    const API = 'https://nn-tracking-api.vercel.app';\n    const form = document.getElementById('nn-track-form');\n    const result = document.getElementById('nn-track-result');\n    const input = document.getElementById('nn-track-input');\n    const btn = document.getElementById('nn-track-btn');\n    const msg = document.getElementById('nn-track-msg');\n    const statusEl = document.getElementById('nn-track-status');\n    const timelineEl = document.getElementById('nn-track-timeline');\n    const activityList = document.getElementById('nn-track-activity-list');\n    const activityToggle = document.getElementById('nn-track-activity-toggle');\n    const backBtn = document.getElementById('nn-track-back');\n\n    let mode = 'order_id';\n\n    document.querySelectorAll('.nn-track__radio').forEach(function(label){\n      label.addEventListener('click', function(){\n        document.querySelectorAll('.nn-track__radio').forEach(function(l){ l.classList.remove('is-active'); });\n        label.classList.add('is-active');\n        mode = label.dataset.mode;\n        input.placeholder = mode === 'order_id' ? 'Enter your Order ID' : 'Enter AWB / Tracking ID';\n        input.value = '';\n        msg.textContent = '';\n      });\n    });\n\n    input.addEventListener('keydown', function(e){ if(e.key === 'Enter') doTrack(); });\n    btn.addEventListener('click', doTrack);\n    backBtn.addEventListener('click', function(){\n      result.style.display = 'none';\n      form.style.display = '';\n      input.value = '';\n      msg.textContent = '';\n    });\n\n    activityToggle.addEventListener('click', function(){\n      var list = document.getElementById('nn-track-activity-list');\n      var isOpen = list.style.display !== 'none';\n      list.style.display = isOpen ? 'none' : '';\n      activityToggle.classList.toggle('is-open', !isOpen);\n    });\n\n    function doTrack(){\n      var val = input.value.trim();\n      if(!val){ msg.className = 'nn-track__msg nn-track__msg--error'; msg.textContent = 'Please enter a valid ID'; return; }\n\n      msg.className = 'nn-track__msg nn-track__msg--loading';\n      msg.innerHTML = '<span class=\"nn-track__loader\"></span> Tracking your order...';\n      btn.disabled = true;\n\n      var url = API + '/api/track?' + (mode === 'order_id' ? 'order_id=' : 'awb=') + encodeURIComponent(val);\n\n      fetch(url)\n        .then(function(r){ return r.json().then(function(d){ return {ok: r.ok, data: d}; }); })\n        .then(function(res){\n          btn.disabled = false;\n          if(!res.ok || res.data.error){\n            msg.className = 'nn-track__msg nn-track__msg--error';\n            msg.textContent = res.data.status === 404 ? 'No tracking data found for this ID. Please check and try again.' : (res.data.error || 'Something went wrong');\n            return;\n          }\n          msg.textContent = '';\n          renderResult(res.data);\n        })\n        .catch(function(){\n          btn.disabled = false;\n          msg.className = 'nn-track__msg nn-track__msg--error';\n          msg.textContent = 'Network error. Please try again.';\n        });\n    }\n\n    var STEPS = [\n      {key: 'ordered',   label: 'Ordered',   codes: []},\n      {key: 'dispatched',label: 'Dispatched', codes: ['6','42','OP']},\n      {key: 'transit',   label: 'In Transit', codes: ['18','38','OT']},\n      {key: 'ofd',       label: 'Out for Delivery', codes: ['17','OO']},\n      {key: 'delivered', label: 'Delivered',  codes: ['7','DL']}\n    ];\n\n    function mapStatus(shipmentStatus){\n      if(shipmentStatus == 7) return 4;\n      if(shipmentStatus == 17) return 3;\n      if(shipmentStatus == 18 || shipmentStatus == 38) return 2;\n      if(shipmentStatus == 6 || shipmentStatus == 42) return 1;\n      if(shipmentStatus >= 1) return 0;\n      return 0;\n    }\n\n    function fmtDate(d){\n      if(!d) return '';\n      try {\n        var dt = new Date(d);\n        return dt.toLocaleDateString('en-IN',{day:'numeric',month:'short'}) + ', ' + dt.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',hour12:true});\n      } catch(e){ return d; }\n    }\n\n    function statusIcon(idx){\n      if(idx >= 4) return '<svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg>';\n      return '<svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>';\n    }\n\n    function renderResult(data){\n      var td = data.tracking_data || data;\n      var track = td.shipment_track ? td.shipment_track[0] : {};\n      var activities = td.shipment_track_activities || [];\n      var currentStep = mapStatus(td.shipment_status);\n      var isDelivered = td.shipment_status == 7;\n\n      var iconClass = isDelivered ? 'nn-track__status-icon--green' : 'nn-track__status-icon--blue';\n      var statusText = track.current_status || STEPS[currentStep].label;\n\n      statusEl.innerHTML =\n        '<div class=\"nn-track__status-top\">' +\n          '<div class=\"nn-track__status-icon ' + iconClass + '\">' + statusIcon(currentStep) + '</div>' +\n          '<div><div class=\"nn-track__status-label\">' + statusText + '</div>' +\n            (track.edd && !isDelivered ? '<div class=\"nn-track__status-sub\">Expected by ' + fmtDate(track.edd) + '</div>' : '') +\n            (isDelivered && track.delivered_date ? '<div class=\"nn-track__status-sub\">Delivered on ' + fmtDate(track.delivered_date) + '</div>' : '') +\n          '</div>' +\n        '</div>' +\n        '<div class=\"nn-track__info-row\">' +\n          (track.awb_code ? '<div class=\"nn-track__info-item\"><span>AWB:</span><span>' + track.awb_code + '</span></div>' : '') +\n          (track.order_id ? '<div class=\"nn-track__info-item\"><span>Order:</span><span>#' + track.order_id + '</span></div>' : '') +\n          (track.destination ? '<div class=\"nn-track__info-item\"><span>Destination:</span><span>' + track.destination + '</span></div>' : '') +\n        '</div>';\n\n      var stepDates = ['','','','',''];\n      activities.slice().reverse().forEach(function(a){\n        var code = a['sr-status'] || '';\n        STEPS.forEach(function(s, si){\n          if(s.codes.indexOf(code) > -1 && !stepDates[si]) stepDates[si] = a.date;\n        });\n      });\n      if(isDelivered && track.delivered_date) stepDates[4] = track.delivered_date;\n\n      var progressPct = isDelivered ? 100 : (currentStep === 0 ? 0 : (currentStep / (STEPS.length - 1)) * 100);\n\n      var stepsHtml = '<div class=\"nn-track__steps\"><div class=\"nn-track__progress-bar\" style=\"width:' + progressPct + '%\"></div>';\n      STEPS.forEach(function(s, i){\n        var cls = (i < currentStep || (i === currentStep && isDelivered)) ? 'is-done' : (i === currentStep ? 'is-current' : '');\n        var check = i <= currentStep ? '<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"white\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>' : '';\n        stepsHtml += '<div class=\"nn-track__step ' + cls + '\">' +\n          '<div class=\"nn-track__step-dot\">' + check + '</div>' +\n          '<div class=\"nn-track__step-label\">' + s.label + '</div>' +\n          (stepDates[i] ? '<div class=\"nn-track__step-date\">' + fmtDate(stepDates[i]) + '</div>' : '') +\n        '</div>';\n      });\n      stepsHtml += '</div>';\n      timelineEl.innerHTML = stepsHtml;\n\n      var actHtml = '';\n      activities.forEach(function(a){\n        actHtml += '<div class=\"nn-track__activity-item\">' +\n          '<div class=\"nn-track__activity-dot\"></div>' +\n          '<div><div class=\"nn-track__activity-text\">' + (a.activity || a.status || '') + '</div>' +\n          '<div class=\"nn-track__activity-meta\">' + fmtDate(a.date) + (a.location && a.location !== 'NA' ? ' &middot; ' + a.location : '') + '</div></div></div>';\n      });\n      activityList.innerHTML = actHtml || '<p style=\"padding:8px 0;color:var(--nn-bark);font-size:.8125rem;\">No activity details available.</p>';\n\n      form.style.display = 'none';\n      result.style.display = '';\n      activityToggle.classList.remove('is-open');\n      document.getElementById('nn-track-activity-list').style.display = 'none';\n    }\n\n    var params = new URLSearchParams(window.location.search);\n    if(params.get('order_id')){\n      input.value = params.get('order_id');\n      mode = 'order_id';\n      doTrack();\n    } else if(params.get('awb')){\n      input.value = params.get('awb');\n      mode = 'awb';\n      document.querySelectorAll('.nn-track__radio').forEach(function(l){\n        l.classList.toggle('is-active', l.dataset.mode === 'awb');\n      });\n      doTrack();\n    }\n  })();\n</script>\n\n\n</section>\n    "},
};

